"""Original, task-aligned worked examples for every lesson.

These are deliberately distinct from the short code excerpt and answer keys.
Each lesson explains *why*, walks through *how*, shows another concrete
example (a complete Main.java when runnable=True), and points the learner to
the next skill without just handing them the exercise answer.
"""


def G(why, steps, code, result, bridge, *, language='java', runnable=False, label='Фрагмент кода'):
    assert 65 <= len(why) <= 400, why
    assert 2 <= len(steps) <= 4 and all(50 <= len(step) <= 320 for step in steps), steps
    assert len(code.strip()) >= 25 and 25 <= len(result) <= 330, code
    assert 60 <= len(bridge) <= 320, bridge
    assert language in {'java', 'sql', 'xml', 'yaml', 'dockerfile', 'text'}
    if runnable:
        assert language == 'java' and 'public class Main {' in code and 'public static void main(String[] args)' in code
        assert 'System.out.println(' in code
    return dict(why=why, steps=list(steps),
                example=dict(code=code, language=language, runnable=runnable, label=label),
                result=result, bridge=bridge)


