# Literal console output lets readers compare their run line by line. These
# values are authored alongside the examples rather than inferred from prose.
RUNNABLE_OUTPUTS = {
    (1, 0): '16\nМира\ntrue',
    (1, 1): '4000000000',
    (1, 2): '2\n2.75\n3',
    (1, 3): '15',
    (2, 0): 'Возьми зонт',
    (2, 1): 'Зачёт',
    (2, 2): 'Есть место',
    (2, 3): 'Базовый',
    (3, 0): '1\n2\n3',
    (3, 1): '8\n6',
    (3, 2): '12',
    (3, 3): '1\n2',
    (4, 0): 'Шаг 7',
    (10, 4): 'Пример',
}
assert set(RUNNABLE_OUTPUTS) == {
    (number, index) for number, lessons in GUIDES.items()
    for index, guide in enumerate(lessons) if guide['example']['runnable']
}
for (number, index), stdout in RUNNABLE_OUTPUTS.items():
    GUIDES[number][index]['example']['stdout'] = stdout


def guide_for(module_number, lesson_index):
    """Return an authored lesson guide; fail loudly when authoring is incomplete."""
    from copy import deepcopy
    return deepcopy(GUIDES[module_number][lesson_index])
